export interface EncounterSetup { readonly version: 1; readonly bossLife: number; readonly attacksPerTurn: number; readonly minAttackValue: number; readonly maxAttackValue: number; readonly chapterNumber: number; readonly bossAbility: BossAbility; readonly playerAdditions: readonly string[]; readonly bossAdditions: readonly string[]; readonly attackTiming: "clear-priority"; readonly winRoute: "first-uncompleted"; readonly lossRoute: "retry"; }
export interface GameConfig { readonly version: 1; readonly startingLife: 42; readonly handSize: number; }
export interface ContentBinding { readonly mechanicProgramVersion?: "gauntlet.mechanic-program.v1"; readonly factionFamilyVersion?: "gauntlet.faction-families.v1" | "gauntlet.faction-families.v2"; readonly encounterAiVersion?: "gauntlet.encounter-ai.v1"; readonly mechanicVersion?: "gauntlet.mechanics.v1" | "gauntlet.mechanics.v2"; readonly compositionVersion?: "gauntlet.composition.armament.v1"; readonly authoredRelease: string; readonly rulesVersion: string; readonly cardEffectContractVersion: "gauntlet.card-effects.v1"; readonly factionEffectContractVersion: "gauntlet.faction-effects.v1"; readonly encounterContractVersion: "gauntlet.encounter-setup.v1"; readonly assetManifestVersion: string; readonly gameConfigVersion: "gauntlet.game-config.v1"; }
export interface CardPresentation { readonly printingId?: string; readonly printingRevision?: string; readonly gameplayRevision?: string; readonly releaseId: string; readonly assetManifestVersion: string; readonly illustration?: string | null; readonly faces?: Readonly<Record<string, string | null>>; readonly face?: string | null; readonly composed: boolean; readonly illustrationAssetId?: string | null; readonly illustrationDigest?: string | null; }

export interface ComposedArmament { readonly id: "composed-rumin-armament"; readonly version: 1; readonly abilities: ReadonlyArray<{ readonly timing: "arm"; readonly cost: "attack-payment-and-source"; readonly limit: "once-per-arming"; readonly condition: { readonly kind: "always" | "diamondsPaid" } | { readonly kind: "overpay" | "attackValue" | "attackNumber"; readonly amount: number }; readonly effects: ReadonlyArray<{ readonly kind: "attackBonus"; readonly amount: number; readonly target: "attacker"; readonly duration: "combat" } | { readonly kind: "gainLife"; readonly amount: number; readonly target: "self"; readonly duration: "instant" }>; }>; }
export interface AuthoredMechanicReference { readonly id: "authored-mechanic"; readonly version: 1 | 2; readonly mechanicId: string; }
/** Exact definition shape is validated by its immutable interpreter contract. */
export interface CapturedMechanic extends AuthoredMechanicReference { readonly definition: Readonly<Record<string, unknown>>; readonly revision: string; }
export interface MechanicProgram { readonly id: "mechanic-program"; readonly version: 1; readonly mechanics: ReadonlyArray<AuthoredMechanicReference | CapturedMechanic>; readonly armament: ComposedArmament | null; }
export type CardEffect = LegacyCardEffect | ComposedArmament | AuthoredMechanicReference | CapturedMechanic | MechanicProgram;

export type EncounterAiProfile = "scripted-pressure" | "support-first";
export interface PackComposition { readonly version: 1; readonly slots: readonly ("common" | "uncommon" | "rare" | "mythic" | "wild" | "face")[]; readonly wildMythicPercent: number; }
